-- Projects

insert into public.projects (id, slug, title, label, summary, description, problem, approach, results, learnings,
  tools, cover_url, video_url, prototype_url, github_url, demo_url, report_url, start_date, end_date, is_ongoing,
  featured, status, position, published_at)
values (md5('project:eventura')::uuid, 'eventura', '{"en":"Eventura — Smart Event Management","ar":"إيفنتورا — إدارة الفعاليات الذكية"}'::jsonb, '{"en":"Senior Capstone · Qatar University","ar":"مشروع التخرج · جامعة قطر"}'::jsonb, '{"en":"A web + mobile event platform with QR check-ins under 3 seconds, GPS geofencing, gamified booth challenges and live analytics — load-tested with 500 concurrent users.","ar":"منصة فعاليات للويب والجوال بتسجيل حضور عبر QR في أقل من 3 ثوانٍ، وسياج جغرافي، وتحديات تفاعلية للأجنحة، وتحليلات لحظية — اختُبرت مع 500 مستخدم متزامن."}'::jsonb,
  '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Eventura is a modular, cloud-backed event management system for booth-based events — conferences, exhibitions and university expos. Organizers and exhibitors use a web dashboard; visitors use a bilingual (EN/AR) Flutter mobile app. Both share one real-time Supabase backend."}]},{"type":"paragraph","content":[{"type":"text","text":"Built by a team of four (Layan Alwattar, Amna Osman, Reem Aladbi, Khawlah Daraan), supervised by Dr. Khaled Shaban and Dr. Saeed Salem."}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"إيفنتورا نظام معياري سحابي لإدارة الفعاليات القائمة على الأجنحة — المؤتمرات والمعارض ومعارض الجامعات. يستخدم المنظّمون والعارضون لوحة تحكم على الويب، ويستخدم الزوّار تطبيق جوال ثنائي اللغة مبنياً بـ Flutter، ويتشارك الجميع خلفية Supabase واحدة تعمل لحظياً."}]},{"type":"paragraph","content":[{"type":"text","text":"نفّذه فريق من أربع طالبات (ليان الوتار، آمنة عثمان، ريم العدبي، خولة دعران) بإشراف د. خالد شعبان ود. سعيد سالم."}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Event platforms tend to be either rigid or complex and costly. Organizers face:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Long check-in queues and paper sign-ups"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fragmented tools for registration, badges and surveys"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No real-time view of who is attending, where, and when"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Low attendee engagement during long events"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تميل منصات الفعاليات إلى أن تكون إما جامدة أو معقدة ومكلفة. ويواجه المنظّمون:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"طوابير تسجيل طويلة وأوراق تسجيل يدوية"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أدوات متفرقة للتسجيل والشارات والاستبيانات"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"غياب الرؤية اللحظية لمن يحضر وأين ومتى"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضعف تفاعل الحضور خلال الفعاليات الطويلة"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I worked on the Flutter mobile app with my teammate Reem, focusing on the backend and integration side:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supabase in depth: schema design, row-level security, real-time channels that push database changes straight into the UI"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Database functions, triggers and scheduled cron jobs for waitlists, event status updates and auto-checkout"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Camera-based QR scanning and QR generation, GPS and geofencing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A context-aware notification system reacting to geofence transitions, inactivity timers and user roles"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Full Arabic/English support with RTL, plus light and dark themes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Custom SMTP for transactional email and shared API contracts with the web team"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"عملت على تطبيق الجوال المبني بـ Flutter مع زميلتي ريم، مع التركيز على جانب الخلفية والتكامل:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supabase بعمق: تصميم المخطط، وأمان مستوى الصفوف، والقنوات اللحظية التي تنقل تغييرات قاعدة البيانات مباشرة إلى الواجهة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دوال ومشغّلات ومهام مجدولة لقوائم الانتظار وتحديث حالة الفعاليات والخروج التلقائي"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مسح رموز QR بالكاميرا وتوليدها، وGPS والسياج الجغرافي"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"نظام إشعارات ذكي يستجيب لدخول النطاقات الجغرافية ومؤقتات الخمول وأدوار المستخدمين"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دعم كامل للعربية والإنجليزية مع الاتجاه من اليمين لليسار، ووضعان فاتح وداكن"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"بريد SMTP مخصص وعقود واجهات برمجية مشتركة مع فريق الويب"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"QR scans respond within "},{"type":"text","text":"3 seconds","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Supports "},{"type":"text","text":"500 concurrent users","marks":[{"type":"bold"}]},{"type":"text","text":" without noticeable degradation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New users completed registration and check-in within minutes, without training"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Live heatmaps, hour-by-hour engagement charts, competition judging and one-click PDF reports for organizers"}]}]}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"استجابة مسح QR خلال "},{"type":"text","text":"3 ثوانٍ","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دعم "},{"type":"text","text":"500 مستخدم متزامن","marks":[{"type":"bold"}]},{"type":"text","text":" دون تراجع ملحوظ في الأداء"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أتمّ المستخدمون الجدد التسجيل وتسجيل الحضور خلال دقائق دون تدريب مسبق"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"خرائط حرارية لحظية، ومخططات تفاعل بالساعة، وتحكيم للمسابقات، وتقارير PDF بنقرة واحدة للمنظّمين"}]}]}]}]}}'::jsonb, '{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plan early and ship iteratively — small, testable slices beat any single tool or framework"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clear written communication beats a clever solution nobody else understands"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat integration as real work, with its own timeline"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stay adaptable: calmly accepting requirement changes is the real skill"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Carrying a project this complete gave me proof that I can take an idea from an empty repository to a working application."}]}]},"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"خطّط مبكراً وأطلق على مراحل — الأجزاء الصغيرة القابلة للاختبار أفضل من أي أداة أو إطار عمل"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التواصل الكتابي الواضح أهم من حلٍّ ذكي لا يفهمه أحد"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التكامل عمل حقيقي يستحق جدولاً زمنياً خاصاً به"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرونة: تقبّل تغيّر المتطلبات بهدوء هو المهارة الحقيقية"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"منحني إنجاز مشروع بهذا الحجم دليلاً على قدرتي على تحويل فكرة من مستودع فارغ إلى تطبيق يعمل."}]}]}}'::jsonb,
  array['Flutter', 'Dart', 'Supabase', 'PostgreSQL', 'Realtime', 'Next.js', 'React', 'Tailwind', 'Leaflet', 'Geofencing']::text[], '/content/eventura/poster.webp', null, null, null,
  null, null, '2025-09-01', '2026-05-31', false,
  true, 'published', 0, now())
on conflict (slug) do nothing;

