select md5('chart:ai-simulation-tools-higher-education')::uuid, md5('dataset:ai-simulation-tools-higher-education')::uuid, '{"en":"Scale reliability (Cronbach’s α)","ar":"ثبات المقاييس (معامل كرونباخ ألفا)"}'::jsonb, '{"en":"All scales exceed 0.80, indicating strong internal consistency (preliminary analysis, n = 87).","ar":"تتجاوز جميع المقاييس 0.80، ما يدل على اتساق داخلي قوي (تحليل أولي، n = 87)."}'::jsonb, 'bar',
